# apply_loop_and_run.py — installs 6 files, backfills loopstats, and
# retrains the calibrated GBM with loop-data rolling features.
import base64, sys, pathlib, subprocess, os

FILES = {
    'src/scrape/nascar_loop.py': '',
    'src/cli/backfill_loop.py': '',
    'src/features/loop_rolling.py': '',
    'src/features/build_features.py': '',
    'src/models/gbm_ranker.py': '',
    'src/eval/backtest_gbm_calibrated.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")

    # Backfill loopstats if not present or if user forced --refresh.
    force = "--refresh" in sys.argv
    loop_path = pathlib.Path("data/processed/loopstats.parquet")
    if not loop_path.exists() or force:
        print("\n=== fetching loopstats for all races ===")
        subprocess.run([sys.executable, "-m", "src.cli.backfill_loop"], check=True)
    else:
        print(f"\nloopstats.parquet exists ({loop_path.stat().st_size} bytes) — skipping backfill "
              "(pass --refresh to re-fetch)")

    import pandas as pd
    from src.eval.backtest_gbm_calibrated import backtest_gbm_calibrated, summarize_test

    races = pd.read_parquet("data/processed/races.parquet").sort_values("date").reset_index(drop=True)
    entries = pd.read_parquet("data/processed/entries.parquet")
    sessions = pd.read_parquet("data/processed/sessions.parquet")
    loopstats = pd.read_parquet("data/processed/loopstats.parquet")
    print(f"loopstats rows: {len(loopstats)}, races covered: {loopstats['race_id_short'].nunique()}")

    print("\n=== GBM + loop features (train=2022, val=2023, test=2024-2026) ===")
    out = backtest_gbm_calibrated(
        races, entries, sessions,
        train_end="2023-01-01", val_end="2024-01-01",
        loopstats=loopstats,
    )
    print("\n== TEST (T only) ==")
    print(summarize_test(out["test_metrics"]).round(4).to_string())
    print("\n== TEST (T + isotonic) ==")
    print(summarize_test(out["test_metrics_iso"]).round(4).to_string())

    # Feature importance — should surface the loop features prominently.
    try:
        booster = out["model"].booster
        imp = pd.DataFrame({
            "feature": booster.feature_name(),
            "gain": booster.feature_importance(importance_type="gain"),
        }).sort_values("gain", ascending=False).head(15)
        print("\nTop 15 features by gain:")
        print(imp.to_string(index=False))
    except Exception as e:
        print(f"(feature importance skipped: {e})")

if __name__ == "__main__":
    main()
